using System;
using LingGuangV05.Core.Forum;
using NUnit.Framework;
namespace LingGuangV05.Tests
{
    public sealed class LaoZhouQuestionTests
    {
        static LaoZhouQaState Linked(){var s=new LaoZhouQaState{yyInvitationSent=true};Assert.IsTrue(LaoZhouQuestions.Accept(s,42));return s;}
        [Test] public void OldStateIsUnansweredAndDoesNotGrantAcceptance(){var s=new LaoZhouQaState();Assert.AreEqual(0,s.first.choice);Assert.AreEqual(0,s.second.choice);Assert.IsFalse(LaoZhouQuestions.Linked(s));Assert.IsFalse(LaoZhouQuestions.Accept(s,1));}
        [Test] public void AcceptanceRequiresOfferAndIsIdempotent(){var s=Linked();Assert.AreEqual("tieba_dm_accept",s.yyLinkSource);Assert.IsFalse(LaoZhouQuestions.Accept(s,99));Assert.AreEqual(42,s.yyLinkedAt);}
        [Test] public void LegacyContactRequiresBothSavedProvenanceAndHistory(){foreach(bool saved in new[]{false,true})foreach(bool history in new[]{false,true}){var s=new LaoZhouQaState();Assert.AreEqual(saved&&history,LaoZhouQuestions.MigrateLegacy(s,saved,history));Assert.AreEqual(saved&&history,LaoZhouQuestions.Linked(s));Assert.AreEqual(0,s.first.choice);Assert.IsFalse(LaoZhouQuestions.MigrateLegacy(s,true,true));}}
        [Test] public void BothLanguagesHaveExactlyTwoTimesThreeBranches(){for(int q=1;q<=2;q++)foreach(bool en in new[]{false,true}){Assert.AreEqual(3,LaoZhouQuestions.Choices(q,en).Length);for(int c=1;c<=3;c++){Assert.AreEqual(c,LaoZhouQuestions.ChoiceIndex(q,LaoZhouQuestions.Choices(q,en)[c-1]));Assert.IsNotEmpty(LaoZhouQuestions.Response(q,c,en));}}}
        [Test] public void PublicFirstReplyDoesNotRequireYyOrGrantYy(){var s=new LaoZhouQaState();Assert.IsTrue(LaoZhouQuestions.Choose(s,1,3,"tieba_public",10));Assert.IsFalse(LaoZhouQuestions.Linked(s));Assert.IsFalse(LaoZhouQuestions.Choose(s,2,1,"yy",20));}
        [Test] public void EveryCrossChannelDoubleClickKeepsTheFirstActualChoice(){foreach(string firstChannel in new[]{"tieba_public","yy"})for(int choice=1;choice<=3;choice++){var s=Linked();Assert.IsTrue(LaoZhouQuestions.Choose(s,1,choice,firstChannel,10));foreach(string channel in new[]{"tieba_public","yy"})for(int retry=1;retry<=3;retry++)Assert.IsFalse(LaoZhouQuestions.Choose(s,1,retry,channel,20));Assert.AreEqual(choice,s.first.choice);Assert.AreEqual(firstChannel,s.first.channel);Assert.AreEqual(10,s.first.answeredAt);}}
        [Test] public void StageOnlySchedulesAndNeverCompletesOrUnlocks(){var s=Linked();Assert.AreEqual(0,LaoZhouQuestions.Due(s,6,false));Assert.AreEqual(2,LaoZhouQuestions.Due(s,6,true));Assert.AreEqual(0,s.first.choice);Assert.AreEqual(0,s.second.choice);Assert.AreEqual(1,LaoZhouQuestions.Due(s,2,true));s.first.yyOffered=true;Assert.AreEqual(0,LaoZhouQuestions.Due(s,2,true));Assert.AreEqual(2,LaoZhouQuestions.Due(s,6,true));s.second.yyOffered=true;Assert.AreEqual(0,LaoZhouQuestions.Due(s,6,true));}
        [Test] public void Q2OpeningRemembersOnlyActualQ1Completion(){foreach(bool en in new[]{false,true}){string fresh=string.Join(" ",LaoZhouQuestions.Opening(2,false,en));string known=string.Join(" ",LaoZhouQuestions.Opening(2,true,en));Assert.AreNotEqual(fresh,known);Assert.IsFalse(fresh.Contains("还记得")||fresh.Contains("Remember when"));Assert.IsFalse(known.Contains("考试")||known.Contains("exam"));}}
        [Test] public void PrivateAndUnviewedSourcesAreRejected(){var s=Linked();foreach(string source in new[]{"stage","training","equipment","exam","book","other_dm","public_unviewed","public_unlinked"})Assert.IsFalse(LaoZhouQuestions.Observe(s,source,source,"PRIVATE_SECRET",10));Assert.IsFalse(LaoZhouQuestions.VisibleContext(s,false).Contains("PRIVATE_SECRET"));}
        [Test] public void ScopedFactsKeepTextSourceTimeAndDeduplicate(){var s=Linked();Assert.IsTrue(LaoZhouQuestions.Observe(s,"fact1","tieba_dm","I own one old card.",23));Assert.IsFalse(LaoZhouQuestions.Observe(s,"fact1","tieba_dm","not the actual statement",40));Assert.AreEqual(1,s.facts.Count);Assert.AreEqual(23,s.facts[0].seenAt);StringAssert.Contains("I own one old card.",LaoZhouQuestions.VisibleContext(s,true));Assert.IsTrue(LaoZhouQuestions.Observe(s,"fact2","tieba_public_read_linked","actual public answer",25));}
        [Test] public void UnacceptedYyCannotCreateFacts(){var s=new LaoZhouQaState();Assert.IsFalse(LaoZhouQuestions.Observe(s,"x","yy_dm","private",1));Assert.AreEqual(0,s.facts.Count);}
        [Test] public void InvalidChoicesDoNotPartiallyMutate(){var s=Linked();foreach(int n in new[]{0,3})Assert.IsFalse(LaoZhouQuestions.Choose(s,n,1,"yy",1));foreach(int c in new[]{-1,0,4})Assert.IsFalse(LaoZhouQuestions.Choose(s,1,c,"yy",1));Assert.IsFalse(LaoZhouQuestions.Choose(s,2,1,"tieba_public",1));Assert.AreEqual(0,s.first.choice);Assert.AreEqual(0,s.second.choice);}
        [Test] public void NullLegacyFieldsRepairWithoutCompletingAnything(){var s=new LaoZhouQaState{first=null,second=null,facts=null,yyLinkSource=null};LaoZhouQuestions.Repair(s);Assert.AreEqual(0,s.first.choice);Assert.AreEqual(0,s.second.choice);Assert.AreEqual(0,s.facts.Count);Assert.IsFalse(LaoZhouQuestions.Linked(s));}
    }
}
